"use client";
import { DemoFrame } from "../shared/DemoFrame";
import { ExpandableTabs } from "../beui/ExpandableTabs";
import { Folder, Heart, Clock } from "lucide-react";
export default function Demo() {
  return (
    <DemoFrame>
      <ExpandableTabs
        items={[
          {
            id: "files",
            label: "Files",
            icon: <Folder size={17} />,
            content: (
              <div className="w-60 p-5">
                <h2 className="mb-3 font-medium">Your workspace</h2>
                <p className="text-sm text-muted-foreground">
                  A home for ideas, drafts, and everything in between.
                </p>
              </div>
            ),
          },
          {
            id: "saved",
            label: "Saved",
            icon: <Heart size={17} />,
            content: (
              <div className="w-60 p-5">
                <h2 className="mb-3 font-medium">The good stuff</h2>
                <p className="text-sm text-muted-foreground">
                  Keep the things you want to come back to.
                </p>
              </div>
            ),
          },
          {
            id: "recent",
            label: "Recent",
            icon: <Clock size={17} />,
            content: (
              <div className="w-60 p-5">
                <h2 className="mb-3 font-medium">Pick up where you left off</h2>
                <p className="text-sm text-muted-foreground">
                  Your latest ideas, all in one place.
                </p>
              </div>
            ),
          },
        ]}
      />
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

